// 1. Exact Match is always preferred
void f(int i) {}
void f(long l) {}
f(10);      // Match: f(int)

// 2. Promotion (int->long) over Standard Conversion (int->double)
void g(long l) {}
void g(double d) {}
g(10);      // Match: g(long)

// 3. Ambiguity - Multiple standard conversions of same rank
void h(float f) {}
void h(unsigned int u) {}
h(10);      // ERROR: Ambiguous (int -> float vs int -> unsigned int)

// 4. Const/Non-Const Pointer Resolution
void p(int* ptr) {}
void p(const int* ptr) {}
int x;
p(&x);      // Match: p(int*)
const int cx = 0;
p(&cx);     // Match: p(const int*)
